// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PuttyV2, IERC1271} from "../src/PuttyV2.sol";

contract InvMutTest is Test {
    PuttyV2 c;

    function setUp() public {
        c = new PuttyV2("", 0, address(this));
    }

    function testFuzz_property(
        uint256 strike,
        uint256 premium,
        uint256 duration,
        uint256 expiration,
        uint256 nonce
    ) public {
        strike = bound(strike, 0, type(uint128).max);
        premium = bound(premium, 0, type(uint128).max);
        duration = bound(duration, 0, 9999 days);
        expiration = bound(expiration, 2, type(uint64).max);
        nonce = bound(nonce, 0, type(uint64).max);

        vm.warp(1);

        // Adversarial signer: ERC1271-style maker whose isValidSignature always accepts.
        SigHelper maker = new SigHelper();

        address[] memory whitelist = new address[](0);
        address[] memory floorTokens = new address[](0);
        PuttyV2.ERC20Asset[] memory erc20Assets = new PuttyV2.ERC20Asset[](0);
        PuttyV2.ERC721Asset[] memory erc721Assets = new PuttyV2.ERC721Asset[](0);
        uint256[] memory floorAssetTokenIds = new uint256[](0);

        PuttyV2.Order memory order = PuttyV2.Order({
            maker: address(maker),
            isCall: true,
            isLong: true,
            baseAsset: address(new FakeERC20()),
            strike: strike,
            premium: premium,
            duration: duration,
            expiration: expiration,
            nonce: nonce,
            whitelist: whitelist,
            floorTokens: floorTokens,
            erc20Assets: erc20Assets,
            erc721Assets: erc721Assets
        });

        bytes32 orderHash = c.hashOrder(order);
        bytes32 oppositeHash = c.hashOppositeOrder(order);
        vm.assume(uint256(orderHash) != uint256(oppositeHash));

        bytes memory sig = new bytes(65);

        address filler = address(0xBEEF);
        vm.deal(filler, 1 ether);
        vm.prank(filler);
        c.fillOrder(order, sig, floorAssetTokenIds);

        // Rule: a filled LONG position's expiry is stored under the long position id (the order hash).
        assertTrue(
            c.positionExpirations(uint256(orderHash)) == block.timestamp + duration,
            "long position expiry must be recorded at the long position id"
        );
    }
}

contract SigHelper {
    function isValidSignature(bytes32, bytes memory) external pure returns (bytes4) {
        return IERC1271.isValidSignature.selector;
    }
}

contract FakeERC20 {
    function transferFrom(address, address, uint256) external pure returns (bool) {
        return true;
    }
}
